// script/spec.ts
//
// The specs are JSON, and the TypeScript and the Rust that carry them are
// written from it: neither language is where a number or a name is decided.
// Run as `deno task spec` to write every generated file, and as `deno task
// check:spec` (part of `deno task check`) to fail where one on disk is not
// what its JSON writes.
//
// A generated file is imported as any module is — the client's bundler
// does not take a JSON import from outside its root — and is never edited
// by hand.

import { dirname, join } from "@std/path";

const root = dirname(dirname(new URL(import.meta.url).pathname));

type Output = { path: string; text: string };

// ---- the command table ----

type CmdEntry = { name: string; value: number; doc?: string[] };
type CmdSection = { section: string; doc?: string[] };
type CmdEnum = { name: string; doc?: string[]; format: "hex2" | "hex4" | "dec"; entries: (CmdEntry | CmdSection)[] };
type CmdSpec = { doc: string[]; enums: CmdEnum[] };

function literal(value: number, format: CmdEnum["format"]): string {
  if (format === "dec") return String(value);
  return `0x${value.toString(16).padStart(format === "hex2" ? 2 : 4, "0")}`;
}

function ts_doc(doc: string[], indent: string): string[] {
  if (doc.length === 1) return [`${indent}/** ${doc[0]} */`];
  return doc.map((l, i) => {
    const body = i === 0 ? `${indent}/** ${l}` : l === "" ? `${indent} *` : `${indent} * ${l}`;
    return i === doc.length - 1 ? `${body} */` : body;
  });
}

function rs_doc(doc: string[], indent: string, mark = "///"): string[] {
  return doc.map((l) => (l === "" ? `${indent}${mark}` : `${indent}${mark} ${l}`));
}

function is_section(e: CmdEntry | CmdSection): e is CmdSection {
  return "section" in e;
}

function cmd_ts(spec: CmdSpec): string {
  const out = ["// @pxl/shared/spec/cmd.ts", "//", "// GENERATED by script/spec.ts from cmd.json — do not edit.", "", "/**", ...spec.doc.map((l) => (l === "" ? " *" : ` * ${l}`)), " */"];
  for (const e of spec.enums) {
    out.push("");
    if (e.doc) out.push(...ts_doc(e.doc, ""));
    out.push(`export const enum ${e.name} {`);
    let first = true;
    for (const entry of e.entries) {
      if (is_section(entry)) {
        out.push("", `  // ---- ${entry.section} ----`);
        if (entry.doc) out.push("  //", ...entry.doc.map((l) => (l === "" ? "  //" : `  // ${l}`)));
        out.push("");
      } else {
        if (entry.doc) out.push(...ts_doc(entry.doc, "  ").map((l, i) => (i === 0 ? l : l.replace(/^  \*/, "   *"))));
        out.push(`  ${entry.name} = ${literal(entry.value, e.format)},`);
      }
      first = false;
    }
    void first;
    out.push("}");
  }
  return out.join("\n") + "\n";
}

function pascal(name: string): string {
  return name.toLowerCase().split("_").map((w) => w[0].toUpperCase() + w.slice(1)).join("");
}

const CRUD: Record<number, string> = { 1: "CREATE", 2: "READ", 3: "UPDATE", 4: "DELETE" };

function cmd_rs(spec: CmdSpec): string {
  const out = ["// pxl_shared/spec/cmd.rs", "//", "// GENERATED by script/spec.ts from cmd.json — do not edit.", ""];
  out.push(...rs_doc(spec.doc.map((l) => l.replace("@xpute/core/ipc/cmd.ts", "xpute_core::ipc::cmd")), "", "//!"));
  out.push("", "#![allow(non_camel_case_types, clippy::upper_case_acronyms)]");
  const cmds: CmdEntry[] = [];
  const minors = new Map<string, CmdEnum>();
  const majors = new Map<number, string>();
  for (const e of spec.enums) {
    out.push("");
    if (e.doc) out.push(...rs_doc(e.doc, ""));
    out.push("#[derive(Clone, Copy, Debug, PartialEq, Eq)]", "#[repr(u32)]", `pub enum ${e.name} {`);
    let first = true;
    for (const entry of e.entries) {
      if (is_section(entry)) {
        out.push("", `    // ---- ${entry.section} ----`);
        if (entry.doc) out.push("    //", ...entry.doc.map((l) => (l === "" ? "    //" : `    // ${l}`)));
      } else {
        if (entry.doc) out.push(...rs_doc(entry.doc, "    "));
        out.push(`    ${entry.name} = ${literal(entry.value, e.format)},`);
        if (e.name === "Cmd") cmds.push(entry);
        if (e.name === "Major") majors.set(entry.value, entry.name);
      }
      first = false;
    }
    void first;
    out.push("}");
    if (e.name.endsWith("Minor")) minors.set(e.name, e);
  }
  out.push("", "impl Cmd {", `    const ALL: [Cmd; ${cmds.length}] = [`, ...cmds.map((c) => `        Cmd::${c.name},`), "    ];", "");
  out.push(
    "    /// The command a message's number names, or none for one nobody numbers.",
    "    pub fn of(number: u32) -> Option<Cmd> {",
    "        Cmd::ALL.into_iter().find(|c| *c as u32 == number)",
    "    }",
    "}",
    "",
    "#[cfg(test)]",
    '#[path = "cmd.test.rs"]',
    "mod test;",
  );
  return out.join("\n") + "\n";
}

/// The command table's own test, beside it rather than inside it: every `.rs`
/// in the crates keeps its tests in a `.test.rs` at the same path, and a
/// generated file is no exception.
function cmd_test_rs(spec: CmdSpec): string {
  const cmds: CmdEntry[] = [];
  const minors = new Map<string, CmdEnum>();
  const majors = new Map<number, string>();
  for (const e of spec.enums) {
    for (const entry of e.entries) {
      if (is_section(entry)) continue;
      if (e.name === "Cmd") cmds.push(entry);
      else if (e.name === "Major") majors.set(entry.value, entry.name);
      else minors.set(e.name, e);
    }
  }
  const out: string[] = [
    "// pxl_shared/spec/cmd.test.rs",
    "//",
    "// GENERATED by script/spec.ts from cmd.json — do not edit.",
    "",
    "use super::*;",
    "use xpute_core::ipc::cmd::{cmd, Minor};",
    "",
    "#[test]",
    "fn every_number_is_its_major_and_minor() {",
    "    use Cmd::*;",
    "    let parts = [",
  ];
  for (const c of cmds) {
    if (c.value === 0) continue;
    const major = majors.get(c.value >> 8);
    if (!major) throw new Error(`cmd.json: ${c.name} has no major`);
    const minor_value = c.value & 0xff;
    let minor: string;
    if (minor_value < 0x10) {
      if (!CRUD[minor_value]) throw new Error(`cmd.json: ${c.name}'s minor is no CRUD verb`);
      minor = `Minor::${CRUD[minor_value]}`;
    } else {
      const table = minors.get(`${pascal(major)}Minor`);
      const entry = table?.entries.find((m): m is CmdEntry => !is_section(m) && m.value === minor_value);
      if (!table || !entry) throw new Error(`cmd.json: ${c.name}'s minor is in no ${pascal(major)}Minor`);
      minor = `${table.name}::${entry.name}`;
    }
    out.push(`        (${c.name}, Major::${major} as u32, ${minor} as u32),`);
  }
  out.push(
    "    ];",
    "    for (c, major, minor) in parts {",
    '        assert_eq!(c as u32, cmd(major, minor), "{c:?}");',
    "        assert_eq!(Cmd::of(c as u32), Some(c));",
    "    }",
    "    assert_eq!(Cmd::of(0x0fff), None);",
    "}",
  );
  return out.join("\n") + "\n";
}

async function cmd_outputs(): Promise<Output[]> {
  const spec: CmdSpec = JSON.parse(await Deno.readTextFile(join(root, "packages/pxl/shared/src/spec/cmd.json")));
  return [
    { path: "packages/pxl/shared/src/spec/cmd.ts", text: cmd_ts(spec) },
    { path: "crates/pxl/shared/src/spec/cmd.rs", text: cmd_rs(spec) },
    { path: "crates/pxl/shared/src/spec/cmd.test.rs", text: cmd_test_rs(spec) },
  ];
}

// ---- the cell catalogs ----

type ColorSpec = { _meta?: { description?: string; source?: string } } & Record<string, Record<string, { hex: string; rgb?: number; note?: string }>>;

async function read_json<T>(path: string): Promise<T> {
  return JSON.parse(await Deno.readTextFile(join(root, path)));
}

/** `#RRGGBB` as the one number it is. The JSON is written in hex because a
 * person picks a colour that way; nothing downstream reads it back as text. */
function packed(hex: string): number {
  const m = /^#([0-9a-fA-F]{6})$/.exec(hex);
  if (m === null) throw new Error(`color JSON: "${hex}" is not #RRGGBB`);
  return parseInt(m[1], 16);
}

/** A `$type: "rgb"` leaf: written `#RRGGBB` because a person picks a colour
 * that way, emitted as the one number it is because nothing that lights or
 * blends with it wants text. */
function rgb_literal(hex: string): string {
  return `0x${packed(hex).toString(16).padStart(6, "0")}`;
}

async function color_outputs(): Promise<Output[]> {
  const spec = await read_json<ColorSpec>("packages/pxl/shared/src/spec/cell/color.json");
  const head = [
    "//",
    "// GENERATED by script/spec.ts from color.json — do not edit.",
    "//",
    "// The colour of every cube type: what a cube *is* to the eye when no",
    "// texture is drawn over it — the minimap, the coarse tiers and the",
    "// texture-pack-off path all read this, and the shipped palette carries it",
    "// as each row's `color`. A texture pack decorates these; it does not",
    "// replace them, which is why this table lives with the type numbering in",
    "// spec/cell rather than beside the pack's images.",
  ];
  const packed_spec: ColorSpec = { ...spec };
  for (const [ch, entries] of Object.entries(spec)) {
    if (ch === "_meta") continue;
    packed_spec[ch] = Object.fromEntries(Object.entries(entries as Record<string, { hex: string; note?: string }>).map(([n, e]) => [n, { ...e, rgb: packed(e.hex) }]));
  }
  const ts = ["// @pxl/shared/spec/cell/color.ts", ...head, "", "export default " + JSON.stringify(packed_spec, null, 2).replace(/"([A-Za-z_][A-Za-z0-9_]*)":/g, "$1:").replace(/\n(\s*)\}/g, ",\n$1}").replace(/\n(\s*)\]/g, ",\n$1]") + ";"];
  const rs = ["// pxl_shared/spec/cell/color.rs", ...head, "//", "// `default` is the TypeScript module's default export, the colour file", "// cube.rs builds its colours from.", "", "#![allow(non_upper_case_globals)]", ""];
  rs.push("use super::r#type::{ColorJsonEntry, ColorJsonFile, ColorJsonMeta};", "");
  rs.push("const fn e(hex: &'static str, rgb: u32) -> ColorJsonEntry {", "    ColorJsonEntry { hex, rgb, note: None }", "}", "");
  rs.push("pub const default: ColorJsonFile = ColorJsonFile {");
  const opt = (s?: string) => (s === undefined ? "None" : `Some(${JSON.stringify(s)})`);
  rs.push(spec._meta ? `    _meta: Some(ColorJsonMeta { description: ${opt(spec._meta.description)}, source: ${opt(spec._meta.source)} }),` : "    _meta: None,");
  rs.push("    channels: &[");
  for (const [ch, entries] of Object.entries(spec)) {
    if (ch === "_meta") continue;
    rs.push(`        (`, `            ${JSON.stringify(ch)},`, "            &[");
    for (const [name, entry] of Object.entries(entries as Record<string, { hex: string; note?: string }>)) {
      const rgb = `0x${packed(entry.hex).toString(16).padStart(6, "0")}`;
      rs.push(
        entry.note === undefined
          ? `                (${JSON.stringify(name)}, e(${JSON.stringify(entry.hex)}, ${rgb})),`
          : `                (${JSON.stringify(name)}, ColorJsonEntry { hex: ${JSON.stringify(entry.hex)}, rgb: ${rgb}, note: Some(${JSON.stringify(entry.note)}) }),`,
      );
    }
    rs.push("            ],", "        ),");
  }
  rs.push("    ],", "};");
  return [
    { path: "packages/pxl/shared/src/spec/cell/color.ts", text: ts.join("\n") + "\n" },
    { path: "crates/pxl/shared/src/spec/cell/color.rs", text: rs.join("\n") + "\n" },
  ];
}

type CubeEntry = { name: string; value: number; doc?: string[] } | { section: string };
type CubeSpec = { channels: { name: string; note?: string[]; entries: CubeEntry[] }[] };

async function cube_type_outputs(): Promise<Output[]> {
  const spec = await read_json<CubeSpec>("packages/pxl/shared/src/spec/cell/cube_type.json");
  const head = [
    "//",
    "// GENERATED by script/spec.ts from cube_type.json — do not edit.",
    "//",
    "// The cube catalog's numbering, every channel a name per value; cube.ts",
    "// builds the colours from it and its top comment says what each channel",
    "// is.",
  ];
  const ts = ["// @pxl/shared/spec/cell/cube_type.ts", ...head, "", "export const cube_types = {"];
  const enums: string[] = [];
  const rs = ["// pxl_shared/spec/cell/cube_type.rs", ...head, "", "#![allow(non_camel_case_types, non_upper_case_globals)]", "", "use super::r#type::Channels;", ""];
  rs.push("/// The catalog: a module per channel, each type a constant, and `ENTRIES`", "/// the channel as the object's keys walk it. `CHANNELS` is `cube_types`", "/// itself, walked.", "pub mod cube_types {");
  spec.channels.forEach((ch, ci) => {
    if (ci > 0) ts.push("", `  // ---- ${ch.name} ----`);
    for (const l of ch.note ?? []) ts.push(l === "" ? "  //" : `  // ${l}`);
    if (ci > 0) ts.push("");
    ts.push(`  ${ch.name}: {`);
    if (ci > 0) rs.push("");
    for (const l of ch.note ?? []) rs.push(l === "" ? "    //" : `    // ${l}`);
    rs.push(`    pub mod ${ch.name} {`);
    const names: string[] = [];
    const types: { name: string; lit: string; doc?: string[] }[] = [];
    ch.entries.forEach((e, ei) => {
      if ("section" in e) {
        if (ei > 0) {
          ts.push("");
          rs.push("");
        }
        ts.push(`    // ---- ${e.section} ----`, "");
        rs.push(`        // ---- ${e.section} ----`, "");
        return;
      }
      if (e.doc) ts.push(...ts_doc(e.doc, "    ").map((l, i) => (i === 0 ? l : l.replace(/^    \*/, "     *"))));
      if (e.doc) rs.push(...rs_doc(e.doc, "        "));
      const lit = ch.name === "common" ? `0x${e.value.toString(16).padStart(2, "0")}` : String(e.value);
      ts.push(`    ${e.name}: ${lit},`);
      rs.push(`        pub const ${e.name}: u8 = ${lit};`);
      names.push(e.name);
      types.push({ name: e.name, lit, doc: e.doc });
    });
    ts.push("  },");
    rs.push("", `        pub const ENTRIES: &[(&str, u8)] = &[`, ...names.map((n) => `            (${JSON.stringify(n)}, ${n}),`), "        ];", "    }");
    // The same channel as one type, for Rust, which names a member of a closed
    // set with an enum rather than with the text the JSON spells it out under.
    // TypeScript already has this: `cube_types.land` IS the closed set there,
    // its keys checked by `keyof typeof`.
    const e = pascal(ch.name);
    enums.push("");
    for (const l of ch.note ?? []) enums.push(l === "" ? "    //" : `    // ${l}`);
    enums.push("    #[derive(Clone, Copy, Debug, PartialEq, Eq)]", "    #[repr(u8)]", `    pub enum ${e} {`);
    for (const t of types) {
      if (t.doc) enums.push(...rs_doc(t.doc, "        "));
      enums.push(`        ${t.name} = ${t.lit},`);
    }
    enums.push("    }", "");
    enums.push(`    impl ${e} {`, "        /// Every type the channel gives out, in the JSON's own order.", `        pub const ALL: [${e}; ${types.length}] = [`, ...types.map((t) => `            ${e}::${t.name},`), "        ];", "");
    enums.push(
      "        /// The type a number names, or none for a number the channel",
      "        /// does not give out.",
      `        pub fn of(value: u8) -> Option<${e}> {`,
      `            ${e}::ALL.into_iter().find(|t| *t as u8 == value)`,
      "        }",
      "    }",
    );
  });
  ts.push("} as const satisfies Record<string, Record<string, number>>;");
  rs.push("", "    pub const CHANNELS: &super::Channels = &[", ...spec.channels.map((ch) => `        (${JSON.stringify(ch.name)}, ${ch.name}::ENTRIES),`), "    ];");
  rs.push(...enums, "}");
  return [
    { path: "packages/pxl/shared/src/spec/cell/cube_type.ts", text: ts.join("\n") + "\n" },
    { path: "crates/pxl/shared/src/spec/cell/cube_type.rs", text: rs.join("\n") + "\n" },
  ];
}

// ---- the kit's errno ----
//
// The numbers cross the ring, so both sides have to agree on all fifty-nine;
// they were two hand-kept tables and nothing checked them against each other.
// The name stays out of this: it is the identifier, and `errname()`-shaped
// output derives it from the symbol rather than from a table (sys/error.rs's
// own `stringify!`), so there is nothing here for a reader to drift from.

type ErrnoEntry = { name: string; value: number; doc: string };
type ErrnoSection = { section: string };
type ErrnoSpec = { doc: string[]; entries: (ErrnoEntry | ErrnoSection)[] };

function is_errno_section(e: ErrnoEntry | ErrnoSection): e is ErrnoSection {
  return "section" in e;
}

async function errno_outputs(): Promise<Output[]> {
  const spec = await read_json<ErrnoSpec>("packages/xpute/core/src/sys/errno.json");
  const head = ["//", "// GENERATED by script/spec.ts from errno.json — do not edit.", "//", ...spec.doc.map((l) => `// ${l}`)];

  const ts = ["// @xpute/core/sys/errno.ts", ...head, "", "export const enum Errno {"];
  const rs = ["// xpute_core/sys/errno.rs", ...head, "", "#![allow(clippy::upper_case_acronyms)]", "", "#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]", "#[repr(i32)]", "pub enum Errno {"];
  // Rust lines up its trailing comments per section, as rustfmt leaves them;
  // TypeScript does not, as deno fmt leaves them.
  let run: ErrnoEntry[] = [];
  const flush = () => {
    const width = Math.max(0, ...run.map((e) => `${e.name} = ${e.value},`.length));
    for (const e of run) rs.push(`    ${`${e.name} = ${e.value},`.padEnd(width)} // ${e.doc}`);
    run = [];
  };
  spec.entries.forEach((e, i) => {
    if (is_errno_section(e)) {
      flush();
      rs.push("", `    // ---- ${e.section} ----`);
      ts.push("", `  // ---- ${e.section} ----`, "");
      return;
    }
    run.push(e);
    ts.push(`  ${e.name} = ${e.value}, // ${e.doc}`);
    void i;
  });
  flush();
  rs.push("}", "");
  ts.push("}", "");

  const tail_doc = [
    "Conventions:",
    "- errno == Errno::OK  -> success",
    "- errno != Errno::OK  -> failure",
    "- data == None        -> no payload",
  ];
  rs.push(
    "// Result pair: (errno, data)",
    "//",
    ...tail_doc.map((l) => `// ${l}`),
    "//",
    '// `None` is the canonical "no value / no payload" sentinel, as `null` is on',
    "// the TypeScript side: the empty result slot, nothing about pointers.",
    "pub type ErrnoResult<T> = (Errno, Option<T>);",
  );
  ts.push(
    "// Result pair: [errno, data]",
    "//",
    "// Conventions:",
    "// - errno == Errno.OK  -> success",
    "// - errno != Errno.OK  -> failure",
    "// - data === null      -> no payload",
    "//",
    '// `null` is used as the canonical "no value / no payload" sentinel.',
    "// It does not imply pointer semantics; it is just the empty result slot.",
    "export type ErrnoResult<T> = [Errno, T | null];",
  );
  return [
    { path: "packages/xpute/core/src/sys/errno.ts", text: ts.join("\n") + "\n" },
    { path: "crates/xpute/core/src/sys/errno.rs", text: rs.join("\n") + "\n" },
  ];
}

type DecorSpec = { doc: string[]; decor_types: Record<string, number> };

async function decor_outputs(): Promise<Output[]> {
  const spec = await read_json<DecorSpec>("packages/pxl/shared/src/spec/cell/decor.json");
  const head = ["//", "// GENERATED by script/spec.ts from decor.json — do not edit.", "//", "// [Layer: objects] User-placed decor kind catalog — the cube catalog's own sibling, non-cube content (GLB instances, not a meshed box).", "//"];
  const entries = Object.entries(spec.decor_types);
  const ts = ["// @pxl/shared/spec/cell/decor.ts", ...head, ...spec.doc.map((l) => `// ${l}`), "export const decor_types = {", ...entries.map(([k, v]) => `  ${k}: ${v},`), "} as const satisfies Record<string, number>;", "", "export type DecorId = keyof typeof decor_types;"];
  const rs = ["// pxl_shared/spec/cell/decor.rs", ...head, ...spec.doc.map((l) => `// ${l}`), "#[allow(non_upper_case_globals, non_camel_case_types)]", "pub mod decor_types {", ...entries.map(([k, v]) => `    pub const ${k}: u8 = ${v};`), ""];
  // The catalog as one type, as cube_type.json's channels are: the kernel
  // holds a decor kind as this, and its name is the shell's.
  rs.push("    #[derive(Clone, Copy, Debug, PartialEq, Eq)]", "    #[repr(u8)]", "    pub enum Decor {", ...entries.map(([k, v]) => `        ${k} = ${v},`), "    }", "");
  rs.push("    impl Decor {", "        /// Every kind the catalog gives out, in the JSON's own order.", `        pub const ALL: [Decor; ${entries.length}] = [${entries.map(([k]) => `Decor::${k}`).join(", ")}];`, "");
  rs.push("        /// The kind a number names, or none for a number the catalog does not", "        /// give out.", "        pub fn of(value: u8) -> Option<Decor> {", "            Decor::ALL.into_iter().find(|t| *t as u8 == value)", "        }", "    }", "}", "", "pub type DecorId = decor_types::Decor;");
  return [
    { path: "packages/pxl/shared/src/spec/cell/decor.ts", text: ts.join("\n") + "\n" },
    { path: "crates/pxl/shared/src/spec/cell/decor.rs", text: rs.join("\n") + "\n" },
  ];
}

type PublishedSpec = { doc: string[]; PUBLISHED_VERSION: Record<string, string> };

async function published_outputs(): Promise<Output[]> {
  const spec = await read_json<PublishedSpec>("packages/pxl/shared/src/bake/published.json");
  const kinds = Object.entries(spec.PUBLISHED_VERSION);
  const head = ["//", "// GENERATED by script/spec.ts from published.json — do not edit.", ""];
  const ts = ["// @pxl/shared/bake/published.ts", ...head, "/**", ...spec.doc.map((l) => (l === "" ? " *" : ` * ${l}`)), " */", "export const PUBLISHED_VERSION = {", ...kinds.map(([k, v]) => `  ${k}: ${JSON.stringify(v)},`), "} as const;", "", "export type BakeKind = keyof typeof PUBLISHED_VERSION;"];
  const rs = ["// pxl_shared/bake/published.rs", ...head, ...rs_doc(spec.doc, ""), "pub struct PublishedVersion {", ...kinds.map(([k]) => `    pub ${k}: &'static str,`), "}", ""];
  rs.push("pub const PUBLISHED_VERSION: PublishedVersion = PublishedVersion {", ...kinds.map(([k, v]) => `    ${k}: ${JSON.stringify(v)},`), "};", "");
  rs.push("/// `keyof typeof PUBLISHED_VERSION`.", "#[allow(non_camel_case_types)]", "#[derive(Clone, Copy, Debug, PartialEq, Eq)]", "pub enum BakeKind {", ...kinds.map(([k]) => `    ${k},`), "}", "");
  rs.push("impl PublishedVersion {", "    /// `PUBLISHED_VERSION[kind]`.", "    pub fn of(&self, kind: BakeKind) -> &'static str {", "        match kind {", ...kinds.map(([k]) => `            BakeKind::${k} => self.${k},`), "        }", "    }", "}");
  return [
    { path: "packages/pxl/shared/src/bake/published.ts", text: ts.join("\n") + "\n" },
    { path: "crates/pxl/shared/src/bake/published.rs", text: rs.join("\n") + "\n" },
  ];
}

// ---- data specs ----
//
// A data spec is a JSON file of named values, written as a Rust module of
// nested `pub mod`s of constants, and — where the shell still reads the same
// values — as a TypeScript module of `as const` objects. Most of these are the
// kernel's alone, so they name no `ts` at all.
//
// A leaf is a number, a string, a boolean or an array of one kind of them; a
// number is an f64 unless a `$type` above it says otherwise ("u8".."u64",
// "i32", "f32"), and a u64 is written as a hex string.
//
// A closed set of names — a list of them, an object of entries, or names an
// integer `$type` numbers — is also an enum, as cube_type.json's channels
// are. A string whose `$type` names an enum (a path, or a name this spec
// declares) is that enum's member; `"rgb"` is its packed colour and `"hash"`
// its FNV-1a. Any other string is a `&str`. A value that carries
// its reason is `{ "$value": …, "$doc": [lines] }`; an object's own reason is
// its `$doc` key. The file's `$doc` heads the module.

type DataNode = number | string | boolean | DataNode[] | { [key: string]: DataNode };
type DataSpec = { $doc?: string[]; $ts?: string; $rs?: string; $ts_header?: string; $rs_header?: string } & Record<string, DataNode>;

/** `enums`: the spec's closed sets are also written as Rust enums (see rs_items). */
const DATA_SPECS: { json: string; ts?: string; rs?: string; enums?: true }[] = [
  { json: "crates/pxl/core/src/module/camera/config.json", rs: "crates/pxl/core/src/module/camera/config.rs" },
  { json: "crates/pxl/core/src/module/world/environment/config.json", rs: "crates/pxl/core/src/module/world/environment/config.rs" },
  { json: "crates/pxl/core/src/module/world/environment/theme.json", rs: "crates/pxl/core/src/module/world/environment/theme_spec.rs", enums: true },
  { json: "crates/pxl/core/src/module/world/marker/style.json", rs: "crates/pxl/core/src/module/world/marker/style.rs" },
  { json: "crates/pxl/core/src/module/world/billboard/order.json", rs: "crates/pxl/core/src/module/world/billboard/order.rs" },
  { json: "crates/pxl/core/src/module/world/decor/kind.json", rs: "crates/pxl/core/src/module/world/decor/kind.rs", enums: true },
  { json: "crates/pxl/core/src/app/setting/schema.json", ts: "apps/web/src/app/setting/schema_spec.ts", rs: "crates/pxl/core/src/app/setting/schema_spec.rs" },
  { json: "crates/pxl/core/src/module/world/poi/poi_theme.json", rs: "crates/pxl/core/src/module/world/poi/poi_theme_spec.rs" },
  { json: "crates/pxl/core/src/module/world/character/variant.json", ts: "apps/web/src/module/world/character/variant_spec.ts", rs: "crates/pxl/core/src/module/world/character/variant_spec.rs", enums: true },
  { json: "crates/pxl/core/src/module/world/terrain/config.json", rs: "crates/pxl/core/src/module/world/terrain/config_spec.rs" },
  { json: "crates/pxl/core/src/render/gpu/api.json", ts: "apps/web/src/wasm/gpu_spec.ts", rs: "crates/pxl/core/src/render/gpu/api_spec.rs" },
  { json: "crates/pxl/core/src/module/world/sched/ledger.json", ts: "apps/web/src/module/world/sched/ledger_spec.ts", rs: "crates/pxl/core/src/module/world/sched/ledger_spec.rs" },
  { json: "crates/pxl/core/src/mem/mem.json", ts: "apps/web/src/wasm/mem_spec.ts", rs: "crates/pxl/core/src/mem/spec.rs" },
];

function is_leaf_wrapper(n: DataNode): n is { $value: DataNode; $doc?: string[]; $type?: string } {
  return typeof n === "object" && !Array.isArray(n) && "$value" in n;
}

function ts_literal(n: DataNode, type: string, indent: string): string {
  if (is_leaf_wrapper(n)) return ts_literal(n.$value, (n.$type as string) ?? type, indent);
  if (typeof n === "number") return `${n} as number`;
  if (typeof n === "boolean") return String(n);
  if (typeof n === "string") return type === "u64" ? `${n}n` : type === "rgb" ? rgb_literal(n) : JSON.stringify(n);
  if (Array.isArray(n)) return `[${n.map((e) => ts_literal(e, type, indent)).join(", ")}]`;
  const inner = indent + "  ";
  const t = (n.$type as unknown as string) ?? type;
  const lines = ["{"];
  for (const [k, v] of Object.entries(n)) {
    if (k.startsWith("$")) continue;
    const doc = typeof v === "object" && !Array.isArray(v) ? (v.$doc as unknown as string[] | undefined) : undefined;
    if (doc) lines.push(...ts_doc(doc, inner).map((l, i) => (i === 0 ? l : l.replace(new RegExp(`^${inner}\\*`), `${inner} *`))));
    const key = /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(k) ? k : JSON.stringify(k);
    lines.push(`${inner}${key}: ${ts_literal(v, t, inner)},`);
  }
  lines.push(`${indent}}`);
  return lines.join("\n");
}

/** Where the Rust of a data spec reads a name the JSON types a string with:
 * the module the spec is written as, and the top-level names it declares. */
type RsScope = { module: string; top: Set<string>; enums: boolean };

/** FNV-1a over UTF-8, 64 bits: xpute_core::kit::hash::fnv1a64_bytes. */
function fnv1a64(text: string): string {
  let h = 0xcbf29ce484222325n;
  for (const b of new TextEncoder().encode(text)) {
    h ^= BigInt(b);
    h = BigInt.asUintN(64, h * 0x100000001b3n);
  }
  return `0x${h.toString(16).padStart(16, "0")}`;
}

/** Whether a `$type` names an enum: a path, or a name this spec declares. */
function enum_path(type: string, scope: RsScope): string | null {
  if (/^(u|i)(8|16|32|64)$|^f(32|64)$|^u64$|^rgb$|^hash$|^str$/.test(type)) return null;
  if (type.includes("::") && !scope.top.has(type.split("::")[0])) return type;
  return scope.top.has(type.split("::")[0]) ? `${scope.module}::${type}` : null;
}

/** A leaf as the Rust holds it: a string is the enum member or the hash its
 * `$type` names, and otherwise the string. */
function rs_scalar(n: number | string | boolean, type: string, scope: RsScope): { ty: string; lit: string } {
  if (typeof n === "boolean") return { ty: "bool", lit: String(n) };
  if (typeof n === "string") {
    if (type === "u64") return { ty: "u64", lit: n };
    if (type === "rgb") return { ty: "u32", lit: rgb_literal(n) };
    if (type === "hash") return { ty: "u64", lit: fnv1a64(n) };
    const path = enum_path(type, scope);
    return path === null ? { ty: "&str", lit: JSON.stringify(n) } : { ty: path, lit: `${path}::${rs_ident(n)}` };
  }
  if (type === "f64" || type === "f32") return { ty: type, lit: Number.isInteger(n) ? `${n}.0` : String(n) };
  return { ty: type, lit: String(n) };
}

/** A closed set of names as the Rust names it, the way cube_type.json's
 * channels are: an enum whose members are the JSON's names, numbered as the
 * JSON numbers them — its own numbers where it gives them, its order where it
 * lists them. */
/** An enum's name: the set's name, singular, as cube_type.json's `Land` and
 * decor.json's `Decor` are. */
function enum_name(name: string): string {
  const e = pascal(name);
  return e.endsWith("ies") ? `${e.slice(0, -3)}y` : e.endsWith("s") && !e.endsWith("ss") ? e.slice(0, -1) : e;
}

function rs_enum(name: string, variants: [string, number][], indent: string, out: string[]): void {
  const e = enum_name(name);
  out.push(`${indent}#[derive(Clone, Copy, Debug, PartialEq, Eq)]`, `${indent}#[repr(u8)]`, `${indent}pub enum ${e} {`);
  for (const [v, n] of variants) out.push(`${indent}    ${rs_ident(v)} = ${n},`);
  out.push(`${indent}}`, "");
  out.push(`${indent}impl ${e} {`, `${indent}    /// Every member, in the JSON's own order.`, `${indent}    pub const ALL: [${e}; ${variants.length}] = [`, ...variants.map(([v]) => `${indent}        ${e}::${rs_ident(v)},`), `${indent}    ];`, "");
  out.push(`${indent}    /// The member a number names, or none for a number the set does not`, `${indent}    /// give out.`, `${indent}    pub fn of(value: u8) -> Option<${e}> {`, `${indent}        ${e}::ALL.into_iter().find(|member| *member as u8 == value)`, `${indent}    }`, `${indent}}`);
}

function rs_items(name: string, n: DataNode, type: string, indent: string, out: string[], scope: RsScope): void {
  const doc = is_leaf_wrapper(n) || (typeof n === "object" && !Array.isArray(n)) ? ((n as { $doc?: string[] }).$doc) : undefined;
  const lines: string[] = [];
  if (is_leaf_wrapper(n)) rs_leaf(name, n.$value, n.$type ?? type, indent, lines, scope);
  else if (typeof n !== "object" || Array.isArray(n)) rs_leaf(name, n, type, indent, lines, scope);
  else {
    const t = (n.$type as unknown as string) ?? type;
    const keys = Object.keys(n).filter((k) => !k.startsWith("$"));
    // A catalog: names numbered as decor.json numbers its types — its numbers
    // stay constants, as cube_type.rs keeps both, and are one enum beside them
    // where no two names share one — or a set of entries each an object of its
    // own, numbered in order.
    const numbers = keys.map((k) => n[k]);
    const numbered = scope.enums && keys.length > 0 && /^u(8|16|32)$/.test(t) && numbers.every((v) => typeof v === "number" && v < 256);
    if (numbered && new Set(numbers).size === numbers.length) {
      rs_enum(name, keys.map((k) => [k, n[k] as number]), indent, lines);
      lines.push("");
    } else if (scope.enums && keys.length > 0 && keys.every((k) => typeof n[k] === "object" && !Array.isArray(n[k]) && typeof (n[k] as Record<string, DataNode>).$number === "number")) {
      // A set of entries, each naming its own number as decor.json numbers
      // its kinds; an object whose entries carry none is a structure, not a set.
      rs_enum(name, keys.map((k) => [k, (n[k] as Record<string, DataNode>).$number as number]), indent, lines);
      lines.push("");
    }
    const body: string[] = [];
    for (const k of keys) rs_items(k, n[k], t, indent + "    ", body, scope);
    // Each object's keys are also listed as its `KEYS`, where its closed sets
    // are not enums.
    if (!scope.enums) body.push(`${indent}    pub const KEYS: &[&str] = &[${keys.map((k) => JSON.stringify(k)).join(", ")}];`);
    if (body.length > 0) lines.push(`${indent}pub mod ${rs_ident(name)} {`, ...body, `${indent}}`);
  }
  if (lines.length === 0) return;
  if (doc) out.push(...rs_doc(doc, indent));
  out.push(...lines);
}

const RS_KEYWORDS = new Set(["type", "move", "mod", "fn", "struct", "enum", "match", "loop", "ref", "self", "super", "crate", "use", "where", "impl", "trait", "static", "const", "let", "mut", "in", "for", "if", "else", "while", "return", "true", "false", "as", "box", "dyn", "pub", "unsafe", "async", "await", "break", "continue", "extern", "priv", "virtual", "yield", "try", "macro", "abstract", "become", "do", "final", "override", "typeof", "unsized"]);

function rs_ident(k: string): string {
  const id = k.replace(/[^A-Za-z0-9_]/g, "_");
  return RS_KEYWORDS.has(id) ? `r#${id}` : /^[0-9]/.test(id) ? `_${id}` : id;
}

function rs_leaf(name: string, v: DataNode, type: string, indent: string, out: string[], scope: RsScope): void {
  if (Array.isArray(v)) {
    if (v.length > 0 && typeof v[0] === "string" && type !== "u64" && enum_path(type, scope) === null && type !== "rgb" && type !== "hash") {
      out.push(`${indent}pub const ${rs_ident(name)}: &[&str] = &[${v.map((e) => JSON.stringify(e)).join(", ")}];`);
      // A list of names is a closed set, and an enum beside it.
      if (scope.enums && v.every((e) => typeof e === "string" && /^[A-Za-z_][\w-]*$/.test(e))) rs_enum(name, (v as string[]).map((e, i) => [e, i]), indent, out);
      return;
    }
    const items = v.map((e) => rs_scalar(e as number | string | boolean, type, scope));
    const ty = items[0]?.ty ?? (type === "str" ? "&str" : type);
    out.push(`${indent}pub const ${rs_ident(name)}: [${ty}; ${v.length}] = [${items.map((i) => i.lit).join(", ")}];`);
    return;
  }
  const { ty, lit } = rs_scalar(v as number | string | boolean, type, scope);
  out.push(`${indent}pub const ${rs_ident(name)}: ${ty} = ${lit};`);
}

async function data_outputs(): Promise<Output[]> {
  const outputs: Output[] = [];
  for (const d of DATA_SPECS) {
    const spec = await read_json<DataSpec>(d.json);
    const base = d.json.split("/").pop()!;
    const names = Object.keys(spec).filter((k) => !k.startsWith("$"));
    if (d.ts) {
      const logical = d.ts.replace(/^apps\/web\/src\//, "@pxl/web/");
      const ts = [`// ${logical}`, "//", `// GENERATED by script/spec.ts from ${d.json} — do not edit.`];
      if (spec.$doc) ts.push("//", ...spec.$doc.map((l) => (l === "" ? "//" : `// ${l}`)));
      const body: string[] = [];
      let uses_word = new Set<string>();
      for (const name of names) {
        const n = spec[name];
        body.push("");
        const doc = typeof n === "object" && !Array.isArray(n) ? (n as { $doc?: string[] }).$doc : undefined;
        if (doc) body.push(...ts_doc(doc, "").map((l, i) => (i === 0 ? l : l.replace(/^\*/, " *"))));
        if (is_leaf_wrapper(n) && typeof n.$value !== "object") {
          const t = n.$type ?? "f64";
          const annot = typeof n.$value === "number" || t === "u64" ? t : null;
          if (annot && annot !== "u64") uses_word.add(annot);
          body.push(`export const ${name}${annot && annot !== "u64" ? `: ${annot}` : ""} = ${ts_literal(n, t, "")};`);
        } else {
          body.push(`export const ${name} = ${ts_literal(n, "f64", "")} as const;`);
          // A set numbered by its entries' `$number`, as the Rust enum is:
          // its members' numbers, the way decor.ts lists decor_types.
          const entries = typeof n === "object" && !Array.isArray(n) ? Object.entries(n).filter(([k]) => !k.startsWith("$")) : [];
          if (d.enums && entries.length > 0 && entries.every(([, v]) => typeof v === "object" && !Array.isArray(v) && typeof (v as Record<string, DataNode>).$number === "number")) {
            body.push("", `export const ${enum_name(name)} = {`, ...entries.map(([k, v]) => `  ${k}: ${(v as Record<string, DataNode>).$number},`), "} as const;");
          }
        }
      }
      if (uses_word.size > 0) ts.push("", `import type { ${[...uses_word].sort().join(", ")} } from "@xpute/core/kit/word.ts";`);
      uses_word = new Set();
      outputs.push({ path: d.ts, text: [...ts, ...body].join("\n") + "\n" });
    }
    if (d.rs) {
      const crate_path = d.rs.replace(/^crates\/pxl\/core\/src\//, "pxl_core/");
      const rs = [`// ${crate_path}`, "//", `// GENERATED by script/spec.ts from ${base} — do not edit.`];
      if (spec.$doc) rs.push("//", ...spec.$doc.map((l) => (l === "" ? "//" : `// ${l}`)));
      rs.push("", `#![allow(non_upper_case_globals, non_snake_case, ${d.enums ? "non_camel_case_types, " : ""}dead_code, clippy::excessive_precision)]`);
      const scope: RsScope = { module: d.rs.replace(/^crates\/pxl\/core\/src\//, "crate::").replace(/\.rs$/, "").replaceAll("/", "::"), top: new Set(names.map((k) => enum_name(k)).concat(names)), enums: d.enums === true };
      for (const name of names) {
        const items: string[] = [];
        rs_items(name, spec[name], "f64", "", items, scope);
        if (items.length > 0) rs.push("", ...items);
      }
      outputs.push({ path: d.rs, text: rs.join("\n") + "\n" });
    }
  }
  return outputs;
}

// ---- driver ----

const GENERATORS: (() => Promise<Output[]>)[] = [cmd_outputs, errno_outputs, color_outputs, cube_type_outputs, decor_outputs, published_outputs, data_outputs];

/** A Rust output as `cargo fmt` leaves it, so formatting the crates does not
 * make a generated file stale. */
async function formatted(o: Output): Promise<Output> {
  if (!o.path.endsWith(".rs")) return o;
  const child = new Deno.Command("rustfmt", {
    args: ["--edition", "2021", "--emit", "stdout", "--config-path", join(root, "crates/rustfmt.toml")],
    stdin: "piped",
    stdout: "piped",
    stderr: "piped",
  }).spawn();
  const writer = child.stdin.getWriter();
  await writer.write(new TextEncoder().encode(o.text));
  await writer.close();
  const { code, stdout, stderr } = await child.output();
  if (code !== 0) throw new Error(`rustfmt ${o.path}: ${new TextDecoder().decode(stderr)}`);
  return { path: o.path, text: new TextDecoder().decode(stdout) };
}

const outputs = await Promise.all((await Promise.all(GENERATORS.map((g) => g()))).flat().map(formatted));
if (Deno.args.includes("--write")) {
  for (const o of outputs) {
    await Deno.mkdir(dirname(join(root, o.path)), { recursive: true });
    await Deno.writeTextFile(join(root, o.path), o.text);
    console.log(`wrote ${o.path}`);
  }
} else {
  const stale: string[] = [];
  for (const o of outputs) {
    let on_disk: string | null = null;
    try {
      on_disk = await Deno.readTextFile(join(root, o.path));
    } catch { /* missing */ }
    if (on_disk !== o.text) stale.push(o.path);
  }
  if (stale.length > 0) {
    for (const s of stale) console.error(`spec: ${s} is not what its JSON writes — run \`deno task spec\``);
    Deno.exit(1);
  }
  console.log(`spec: ${outputs.length} generated files are what their JSON writes`);
}
